package com.jnapanam.sportszone.identity.service;
import com.jnapanam.sportszone.common.exception.*;import com.jnapanam.sportszone.notification.provider.NotificationProviderRegistry;import java.security.SecureRandom;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SmsOtpService{
 private static final SecureRandom RANDOM=new SecureRandom();private final JdbcTemplate j;private final PasswordEncoder encoder;private final NotificationProviderRegistry providers;private final boolean testOtpEnabled;private final String testOtp;
 public SmsOtpService(JdbcTemplate j,PasswordEncoder e,NotificationProviderRegistry providers,@Value("${app.security.test-otp-enabled:false}") boolean testOtpEnabled,@Value("${app.security.test-otp:9876}") String testOtp){this.j=j;encoder=e;this.providers=providers;this.testOtpEnabled=testOtpEnabled;this.testOtp=testOtp;}
 @Transactional public void registrationOtp(String mobile){issue(normalize(mobile),"REGISTRATION");}
 @Transactional public void verifyRegistration(String mobile,String otp){verify(normalize(mobile),"REGISTRATION",otp);}
 @Transactional public void passwordResetOtp(String mobile){issue(normalize(mobile),"PASSWORD_RESET");}
 @Transactional public void verifyPasswordReset(String mobile,String otp){verify(normalize(mobile),"PASSWORD_RESET",otp);}
 private void issue(String mobile,String purpose){if(mobile==null||mobile.length()!=10)throw new BadRequestException("A valid 10 digit mobile number is required");Integer recent=j.queryForObject("select count(*) from mobile_otp_challenges where mobile=? and purpose=? and created_at>now()-interval '60 seconds'",Integer.class,mobile,purpose);if(recent!=null&&recent>0)throw new ConflictException("Please wait before requesting another OTP");Integer hourly=j.queryForObject("select count(*) from mobile_otp_challenges where mobile=? and purpose=? and created_at>now()-interval '1 hour'",Integer.class,mobile,purpose);if(hourly!=null&&hourly>=5)throw new ConflictException("OTP request limit reached. Please try again later.");String otp=String.format("%06d",RANDOM.nextInt(1000000));j.update("insert into mobile_otp_challenges(id,purpose,mobile,otp_hash,expires_at) values(?,?,?,?,?)",UUID.randomUUID(),purpose,mobile,encoder.encode(otp),java.sql.Timestamp.from(Instant.now().plusSeconds(300)));if(!testOtpEnabled)providers.sms().sendOtp(mobile,otp);}
 private void verify(String mobile,String purpose,String otp){if(testOtpEnabled&&testOtp.equals(otp))return;if(otp==null||!otp.matches("\\d{6}"))throw new BadRequestException("Invalid OTP");List<Map<String,Object>> rows=j.queryForList("select * from mobile_otp_challenges where mobile=? and purpose=? and verified_at is null order by created_at desc limit 1",mobile,purpose);if(rows.isEmpty())throw new BadRequestException("OTP not requested");Map<String,Object>x=rows.get(0);Instant exp=((java.sql.Timestamp)x.get("expires_at")).toInstant();if(Instant.now().isAfter(exp))throw new BadRequestException("OTP expired");int attempts=((Number)x.get("attempts")).intValue();if(attempts>=5)throw new BadRequestException("Too many OTP attempts");if(!encoder.matches(otp,(String)x.get("otp_hash"))){j.update("update mobile_otp_challenges set attempts=attempts+1 where id=?",x.get("id"));throw new BadRequestException("Invalid OTP");}j.update("update mobile_otp_challenges set verified_at=now() where id=?",x.get("id"));}
 private String normalize(String m){if(m==null)return null;String d=m.replaceAll("\\D","");return d.startsWith("91")&&d.length()==12?d.substring(2):d;}
}
